class Solution {
public:
    int daysBetweenDates(string date1, string date2) {
        auto toDays = [](const string& s) -> long long {
            int y = stoi(s.substr(0, 4));
            int m = stoi(s.substr(5, 2));
            int d = stoi(s.substr(8, 2));
            int prefix[] = {0, 0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334};
            long long total = (long long)y * 365 + (y - 1) / 4 - (y - 1) / 100 + (y - 1) / 400;
            total += prefix[m];
            if (m > 2 && ((y % 4 == 0 && y % 100 != 0) || (y % 400 == 0))) total += 1;
            total += d - 1;
            return total;
        };
        long long a = toDays(date1);
        long long b = toDays(date2);
        return (int)(a > b ? a - b : b - a);
    }
};
